#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// A single lookup may be rate-limited (HTTP 429) by the mirror even when
// every other lookup in the same pass succeeds. Rate limiting is transient:
// the mirror tells us to retry in a few seconds. Rather than fail the whole
// check on one busy response, wait and re-check just the limited packages.
// If a package is still limited after the last retry we give up on that
// one for this run and fail the check instead of reporting a false green.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number.
const limited = deps[run % deps.length];

// The mirror rate-limits at most one lookup per pass and rotates which
// package is limited across runs, so a handful of passes is enough to
// clear every package that is busy.
const MAX_RETRIES = deps.length;
const RETRY_DELAY_MS = 500;

function sleep(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

let pending = deps.slice();
for (let retry = 0; ; retry++) {
  let failed = false;
  const next = [];
  for (const name of pending) {
    if (name === limited) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror busy, retry in a few seconds)" +
        (retry < MAX_RETRIES ? " [retrying]" : " [giving up]"));
      next.push(name);
      continue;
    }
    const meta = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
  if (next.length === 0) break;
  if (retry >= MAX_RETRIES || failed) {
    failed = true;
    break;
  }
  sleep(RETRY_DELAY_MS);
  pending = next;
}

if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

