#!/bin/sh
# Run the dependency check, re-running it with a short wait whenever the
# registry mirror returns a transient HTTP 429. The check verifies
# dependencies one pass at a time (it keeps per-package results between
# runs in .dep-verify-state.json, because the mirror rate-limits at most
# one lookup per run and rotates which package is limited across runs), so
# a few passes are enough to get every dependency verified. Hard errors
# (e.g. a 404 for a version that is not on the mirror) are never retried:
# the check must fail honestly, not spin forever or report a false green.
cd "$(dirname "$0")/.."
MAX=20
i=1
while :; do
  out=$(node scripts/deps-check.js 2>&1); code=$?
  printf '%s\n' "$out"
  [ $code -eq 0 ] && exit 0
  case "$out" in
    *"404 "*)
      exit 1
      ;;
    *"429 Too Many Requests"*)
      [ $i -ge $MAX ] && { echo "giving up after $i attempts; mirror still rate-limited" >&2; exit 1; }
      echo "429 from mirror; sleeping 2s, attempt $((i + 1)) of $MAX" >&2
      i=$((i + 1))
      sleep 2
      ;;
    *)
      exit 1
      ;;
  esac
done

